  const byRegion = {},
    byGroup = {},
    byArea = {};
  D.listings.forEach(l => {
    byRegion[l.region] = (byRegion[l.region] || 0) + 1;
    byGroup[l.group] = (byGroup[l.group] || 0) + 1;
    byArea[l.areaId] = (byArea[l.areaId] || 0) + 1;
  });
  return {
    region: id => byRegion[id] || 0,
    group: id => byGroup[id] || 0,
    area: id => byArea[id] || 0,
    total: D.listings.length
  };
