// --- Generator for every other area ----------------------------------------
function hash(str) {
  let h = 0;
  for (let i = 0; i < str.length; i++) h = h * 31 + str.charCodeAt(i) >>> 0;
  return h;
}
function genArea(cityKey, areaKey, areaName) {
  const sum = window.RT_AREA_SUMMARY[cityKey + "/" + areaKey] || {
    demand: "2BHK homes",
    action: "Add verified listings"
  };
  const h = hash(cityKey + areaKey);
  const searches = 24 + h % 40; // 24–63
  const enquiries = 8 + h % 18; // 8–25
  const live = 3 + h % 7; // 3–9
  const fixes = 1 + h % 4; // 1–4
  const lowEnq = Math.max(1, fixes - 1);
  const matching = Math.max(3, live);
  const d = sum.demand;
  const lower = d.toLowerCase();
  return {
    topNeed: d,
    kpis: [{
      label: "Buyer searches in this area",
      value: String(searches),
      helper: `ReTrends searches and filters for ${areaName} this week`,
      confidence: "Enough data"
    }, {
      label: "Enquiries on your area listings",
      value: String(enquiries),
      helper: `Calls, WhatsApp clicks and forms on your ${areaName} listings`,
      confidence: "Enough data"
    }, {
      label: "Your live listings",
      value: String(live),
      helper: `Live ${areaName} listings on ReTrends`,
      confidence: live >= 4 ? "Enough data" : "Limited data"
    }, {
      label: "Listings needing attention",
      value: String(fixes),
      helper: "Missing location, photos or key details",
      confidence: "Limited data"
    }, {
      label: "Top buyer need",
      value: d,
      helper: `${searches} searches vs ${matching} matching listings`,
      confidence: "Enough data",
      highlight: true
    }],
    insight: {
      text: `Your strongest ${areaName} opportunity is ${lower}. Buyer searches are ahead of visible matching listings, and ${fixes} of your current ${areaName} listings need location or photo fixes.`,
      chips: [d, "Limited matching supply", `${fixes} listings need attention`],
      confidence: live >= 4 ? "Enough data" : "Limited data",
      primary: "demand"
    },
    demand: [{
      need: d,
      searches,
      matching,
      signal: "Searches ahead of supply",
      next: sum.action
    }, {
      need: "Resale " + lower,
      searches: Math.round(searches * 0.7),
      matching: live + 6,
      signal: "Supply appears balanced",
      next: "Improve photos & location"
    }, {
      need: "Homes near schools",
      searches: Math.round(searches * 0.45),
      matching: live + 2,
      signal: "Some matching supply",
      next: "Add school-distance details"
    }, {
      need: "Premium " + lower,
      searches: Math.round(searches * 0.2),
      matching: 3,
      signal: "Limited data",
      next: "Add more verified details"
    }],
    health: {
      needFixes: fixes,
      commonIssue: "Missing location or photos",
      lowEnquiries: lowEnq,
      previews: [{
        title: `Listing 1 — ${areaName}`,
        note: `${60 + h % 40} views · 0 enquiries · location not verified`
      }, {
        title: `Listing 2 — ${areaName}`,
        note: `${30 + h % 25} views · 1 enquiry · photos missing`
      }]
    }
  };
}

// Resolve full insight data for a city/area pair.
window.RT_getInsights = function (cityKey, areaKey, areaName) {
  if (cityKey === "udupi" && areaKey === "malpe") return MALPE;
  return genArea(cityKey, areaKey, areaName);
};
window.RT_DATA_REFRESHED = "16 Jun 2026";
